package com.example.expensetracker.ui.dashboard;
import android.content.*; import android.os.Bundle; import android.view.View; import android.widget.*;
import androidx.appcompat.app.AppCompatActivity; import androidx.lifecycle.ViewModelProvider; import androidx.recyclerview.widget.*;
import com.example.expensetracker.R; import com.example.expensetracker.data.local.TransactionEntity; import com.example.expensetracker.ui.add.AddTransactionActivity; import com.example.expensetracker.ui.transactions.*; import com.example.expensetracker.utils.CurrencyUtils; import com.google.android.material.button.MaterialButton; import com.google.android.material.dialog.MaterialAlertDialogBuilder; import com.google.android.material.textfield.TextInputEditText;
import java.text.SimpleDateFormat; import java.util.*;
public class DashboardActivity extends AppCompatActivity {
 private DashboardViewModel vm; private TextView balance,incomeView,expenseView,empty,budgetText; private ProgressBar progress; private double income=0,expenses=0,monthSpend=0; private TransactionAdapter adapter; private android.content.SharedPreferences prefs;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_dashboard); prefs=getSharedPreferences("finance",MODE_PRIVATE);
 balance=findViewById(R.id.tvBalance);incomeView=findViewById(R.id.tvIncome);expenseView=findViewById(R.id.tvExpenses);empty=findViewById(R.id.tvEmpty);
 int budgetTextId=getResources().getIdentifier("tvBudget","id",getPackageName());budgetText=budgetTextId==0?null:findViewById(budgetTextId);int progressId=getResources().getIdentifier("progressBudget","id",getPackageName());progress=progressId==0?null:findViewById(progressId);
 RecyclerView list=findViewById(R.id.rvRecent);list.setLayoutManager(new LinearLayoutManager(this));adapter=new TransactionAdapter(new ArrayList<>(),this::confirmDelete);list.setAdapter(adapter);
 vm=new ViewModelProvider(this).get(DashboardViewModel.class);vm.getRecent().observe(this,items->{adapter.setItems(items);empty.setVisibility(items==null||items.isEmpty()?View.VISIBLE:View.GONE);});
 vm.getIncome().observe(this,x->{income=x==null?0:x;updateTotals();});vm.getExpenses().observe(this,x->{expenses=x==null?0:x;updateTotals();});
 String month=new SimpleDateFormat("yyyy-MM",Locale.US).format(new Date());vm.getMonthlyExpenses(month).observe(this,x->{monthSpend=x==null?0:x;updateBudget();});
 findViewById(R.id.btnAdd).setOnClickListener(v->startActivity(new Intent(this,AddTransactionActivity.class)));findViewById(R.id.btnAll).setOnClickListener(v->startActivity(new Intent(this,TransactionActivity.class)));
 int budgetId=getResources().getIdentifier("btnBudget","id",getPackageName());if(budgetId!=0)findViewById(budgetId).setOnClickListener(v->setBudget());int analyticsId=getResources().getIdentifier("btnAnalytics","id",getPackageName());if(analyticsId!=0)findViewById(analyticsId).setOnClickListener(v->showInsights());updateBudget(); }
 private void updateTotals(){incomeView.setText(CurrencyUtils.format(income));expenseView.setText(CurrencyUtils.format(expenses));balance.setText(CurrencyUtils.format(income-expenses));}
 private void updateBudget(){if(budgetText==null)return;double budget=prefs.getFloat("monthly_budget",0);if(budget<=0){budgetText.setText("Set a monthly budget to track spending");if(progress!=null)progress.setProgress(0);return;}int pct=(int)Math.min(100,monthSpend/budget*100);budgetText.setText(CurrencyUtils.format(monthSpend)+" spent of "+CurrencyUtils.format(budget)+" this month ("+Math.round(monthSpend/budget*100)+"%)");if(progress!=null)progress.setProgress(pct);}
 private void setBudget(){EditText input=new EditText(this);input.setInputType(8194);input.setHint("Monthly budget in ₹");float old=prefs.getFloat("monthly_budget",0);if(old>0)input.setText(String.valueOf(old));new MaterialAlertDialogBuilder(this).setTitle("Monthly spending limit").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{try{float v=Float.parseFloat(input.getText().toString().trim());if(v<=0)throw new Exception();prefs.edit().putFloat("monthly_budget",v).apply();updateBudget();}catch(Exception e){Toast.makeText(this,"Enter a valid amount above zero",Toast.LENGTH_LONG).show();}}).show();}
 private void showInsights(){String month=new SimpleDateFormat("yyyy-MM",Locale.US).format(new Date());String msg="All-time income: "+CurrencyUtils.format(income)+"\nAll-time expenses: "+CurrencyUtils.format(expenses)+"\nNet balance: "+CurrencyUtils.format(income-expenses)+"\n\nCurrent-month spending: "+CurrencyUtils.format(monthSpend);new MaterialAlertDialogBuilder(this).setTitle("Spending insights").setMessage(msg).setPositiveButton("View transactions",(d,w)->startActivity(new Intent(this,TransactionActivity.class))).setNegativeButton("Close",null).show();}
 private void confirmDelete(TransactionEntity t){new MaterialAlertDialogBuilder(this).setTitle("Delete transaction?").setMessage("This cannot be undone.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->vm.delete(t)).show();}
}
